const TAU=Math.PI*2, PI=Math.PI;
const W0=1280,H0=720;
const P={I:1,D:1,speed:1,T:6,bg:'alpha'};

/* ---------- утилиты ---------- */
const fract=x=>x-Math.floor(x);
const clamp=(x,a=0,b=1)=>x<a?a:x>b?b:x;
const sstep=(a,b,x)=>{x=clamp((x-a)/(b-a));return x*x*(3-2*x)};
function rnd(n,s=0){let h=Math.imul(n|0,0x9E3779B1)^Math.imul((s|0)+1,0x85EBCA6B);h^=h>>>15;h=Math.imul(h,0x2C1B3C6D);h^=h>>>12;h=Math.imul(h,0x297A2D39);h^=h>>>15;return (h>>>0)/4294967296}
const env=p=>sstep(0,.16,p)*(1-sstep(.72,1,p));
const flick=(u,j)=>(.72+.28*Math.sin(TAU*(u*5+j*.37)))*(Math.sin(TAU*(u*13+j*.71))>.8?.4:1);
const add=g=>{g.globalCompositeOperation='lighter'};
const nrm=g=>{g.globalCompositeOperation='source-over'};
const mk=(w,h)=>{const c=document.createElement('canvas');c.width=w;c.height=h;return c};

/* ---------- текстуры ---------- */
function hash2(x,y,s){let h=Math.imul(x,374761393)+Math.imul(y,668265263)+Math.imul(s,2147483647);h=Math.imul(h^(h>>>13),1274126177);return ((h^(h>>>16))>>>0)/4294967296}
function vnoise(x,y,s){const xi=Math.floor(x),yi=Math.floor(y),xf=x-xi,yf=y-yi,u=xf*xf*(3-2*xf),v=yf*yf*(3-2*yf);const a=hash2(xi,yi,s),b=hash2(xi+1,yi,s),c=hash2(xi,yi+1,s),d=hash2(xi+1,yi+1,s);return a+(b-a)*u+(c-a)*v+(a-b-c+d)*u*v}
const fbm=(x,y,s)=>vnoise(x,y,s)*.5+vnoise(x*2,y*2,s+1)*.3+vnoise(x*4,y*4,s+2)*.2;

const PUFF_D=[],PUFF_R=[];
function buildPuffs(){
  const S=192;
  for(let t=0;t<6;t++){
    const cd=mk(S,S),cr=mk(S,S),gd=cd.getContext('2d'),gr=cr.getContext('2d');
    const id=gd.createImageData(S,S),ir=gr.createImageData(S,S);
    for(let y=0;y<S;y++)for(let x=0;x<S;x++){
      const nx=(x-S/2)/(S/2),ny=(y-S/2)/(S/2),r=Math.hypot(nx,ny);
      // лёгкое искажение, чтобы края были рваными
      const wx=x+ (vnoise(x/30,y/30,t*7+3)-.5)*34, wy=y+(vnoise(x/30+9,y/30,t*7+4)-.5)*34;
      const n=fbm(wx/38,wy/38,t*11);
      const fall=1-sstep(.15,.98,r);
      const a=clamp(fall*(n*2.1-.32));
      const i=(y*S+x)*4, sh=n;
      id.data[i]=10+16*sh;id.data[i+1]=6+10*sh;id.data[i+2]=8+12*sh;id.data[i+3]=a*255;
      ir.data[i]=255;ir.data[i+1]=40+40*sh;ir.data[i+2]=22;ir.data[i+3]=a*255;
    }
    gd.putImageData(id,0,0);gr.putImageData(ir,0,0);
    PUFF_D.push(cd);PUFF_R.push(cr);
  }
}
const GL={};
function buildGlows(){
  const S=256;
  const mkg=(stops)=>{const c=mk(S,S),g=c.getContext('2d'),gr=g.createRadialGradient(S/2,S/2,0,S/2,S/2,S/2);stops.forEach(([o,col])=>gr.addColorStop(o,col));g.fillStyle=gr;g.fillRect(0,0,S,S);return c};
  GL.red=mkg([[0,'rgba(255,50,30,1)'],[.25,'rgba(230,30,20,.55)'],[.6,'rgba(170,10,10,.16)'],[1,'rgba(120,0,0,0)']]);
  GL.hot=mkg([[0,'rgba(255,235,210,1)'],[.15,'rgba(255,150,100,.8)'],[.45,'rgba(255,60,30,.25)'],[1,'rgba(200,20,10,0)']]);
  GL.dark=mkg([[0,'rgba(0,0,0,.95)'],[.45,'rgba(0,0,0,.6)'],[.8,'rgba(0,0,0,.15)'],[1,'rgba(0,0,0,0)']]);
}
function glow(g,kind,x,y,rx,a,ry){
  a*=GA;if(a<=.004)return;ry=ry||rx;g.globalAlpha=clamp(a);
  g.drawImage(GL[kind],x-rx,y-ry,rx*2,ry*2);
}
let BEAM;
function buildBeam(){
  const w=128,h=512,c=mk(w,h),g=c.getContext('2d'),id=g.createImageData(w,h);
  for(let y=0;y<h;y++){
    const hh=1-y/(h-1);                      // 0 внизу, 1 вверху
    const alh=Math.pow(1-hh,.85)*(0.25+0.75*(1-sstep(.0,.04,hh)*0+1)) ;
    const top=1-sstep(.55,1,hh);              // мягкое затухание к вершине
    const sig=.16+.3*(1-hh)*.6+.06*hh;
    for(let x=0;x<w;x++){
      const dx=(x/(w-1))*2-1;
      const a=Math.exp(-(dx*dx)/(sig*sig))*top*(0.35+0.65*Math.pow(1-hh,.6));
      const cc=Math.exp(-(dx*dx)/(sig*sig*.12));
      const i=(y*w+x)*4;
      id.data[i]=255;id.data[i+1]=35+150*cc;id.data[i+2]=22+110*cc;id.data[i+3]=clamp(a)*255;
    }
  }
  g.putImageData(id,0,0);BEAM=c;
}

/* ---------- спрайты рун ---------- */
const SPR=[[],[]];
function buildRunes(){
  const S=88,pad=28;
  RUNES.forEach((r,i)=>{
    [false,true].forEach(hot=>{
      const sc=S/Math.max(r.w,r.h);
      const w=Math.ceil(r.w*sc)+pad*2,h=Math.ceil(r.h*sc)+pad*2;
      const c=mk(w,h),g=c.getContext('2d'),p=new Path2D(r.d);
      g.translate((w-r.w*sc)/2,(h-r.h*sc)/2);g.scale(sc,sc);
      g.shadowColor='rgba(255,30,20,1)';g.fillStyle=hot?'#ff9a70':'#ff2f22';
      g.shadowBlur=26;g.fill(p);g.shadowBlur=10;g.fill(p);
      g.shadowBlur=0;g.shadowColor='rgba(0,0,0,0)';
      g.fillStyle=hot?'#ffe6cf':'#ff6a52';g.fill(p);
      SPR[hot?1:0][i]={c,w,h};
    });
  });
}
const NR=()=>RUNES.length;
function rune(g,id,x,y,size,rot,a,hot){
  a*=GA;if(a<=.004||size<1)return;
  const s=SPR[hot?1:0][((id%NR())+NR())%NR()],k=size/88;
  g.globalAlpha=clamp(a);
  if(rot){g.save();g.translate(x,y);g.rotate(rot);g.drawImage(s.c,-s.w/2*k,-s.h/2*k,s.w*k,s.h*k);g.restore()}
  else g.drawImage(s.c,x-s.w/2*k,y-s.h/2*k,s.w*k,s.h*k);
}
function puff(g,t,x,y,r,rot,a,lit){
  g.save();g.translate(x,y);g.rotate(rot);
  g.globalAlpha=clamp(a*GA);g.drawImage(PUFF_D[t%6],-r,-r,2*r,2*r);
  if(lit>.01){g.globalCompositeOperation='lighter';g.globalAlpha=clamp(a*lit*GA);g.drawImage(PUFF_R[t%6],-r,-r,2*r,2*r)}
  g.restore();
}
const cnt=n=>Math.max(1,Math.round(n*P.D));

/* ---------- фон ---------- */
function backdrop(g,W,H){
  g.globalAlpha=1;nrm(g);
  if(P.bg==='alpha'){g.clearRect(0,0,W,H);return}
  g.fillStyle=P.bg==='black'?'#050304':'#0a0607';g.fillRect(0,0,W,H);
  if(P.bg==='ground'){
    const gr=g.createRadialGradient(W/2,H*.78,10,W/2,H*.78,W*.62);
    gr.addColorStop(0,'rgba(62,26,26,.65)');gr.addColorStop(.55,'rgba(28,13,14,.5)');gr.addColorStop(1,'rgba(10,6,7,0)');
    g.fillStyle=gr;g.fillRect(0,0,W,H);
    const fl=g.createLinearGradient(0,H*.6,0,H);
    fl.addColorStop(0,'rgba(0,0,0,0)');fl.addColorStop(1,'rgba(20,10,10,.6)');
    g.fillStyle=fl;g.fillRect(0,H*.6,W,H*.4);
  }
}

/* ---- сценарий: состояние появления/завершения ---- */
const ST={i:1,o:0};
let GA=1;
const ease=x=>1-(1-x)*(1-x);
const easeBack=x=>{x=clamp(x);return 1+2.7*Math.pow(x-1,3)+1.7*Math.pow(x-1,2)};
function wash(g,a,col){if(a<=.004)return;add(g);glow(g,'red',W0*.5,H0*.55,430,a*1.3,260)}
function bolt(g,x0,y0,x1,y1,seed,prog,a){
  let pts=[[x0,y0],[x1,y1]],disp=Math.hypot(x1-x0,y1-y0)*.14;
  for(let it=0;it<6;it++){const np=[];
    for(let k=0;k<pts.length-1;k++){const A=pts[k],B=pts[k+1],dx=B[0]-A[0],dy=B[1]-A[1],len=Math.hypot(dx,dy)||1;
      const r=(rnd(seed*131+it*17+k,3)-.5)*2*disp;np.push(A,[(A[0]+B[0])/2-dy/len*r,(A[1]+B[1])/2+dx/len*r])}
    np.push(pts[pts.length-1]);pts=np;disp*=.55}
  const n=Math.max(2,Math.floor(pts.length*prog));
  const line=(arr,w0,al)=>{[[14,.16,'#ff2a1a'],[6,.45,'#ff7a5a'],[2.4,1,'#fff0e6']].forEach(([w,pa,c])=>{
    g.strokeStyle=c;g.lineWidth=w*w0;g.globalAlpha=clamp(pa*al*a*GA);g.beginPath();arr.forEach((p,k)=>k?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]));g.stroke()})};
  add(g);g.lineJoin='round';
  line(pts.slice(0,n),1,1);
  for(let b=0;b<4;b++){const idx=Math.floor((.12+.7*rnd(seed+b,9))*n);if(idx>=n-1)continue;
    let [px,py]=pts[idx],ang=Math.PI/2+(rnd(seed+b,10)-.5)*2.4;const br=[[px,py]];
    for(let k=0;k<7;k++){ang+=(rnd(seed*7+b*3+k,11)-.5)*1.1;px+=Math.cos(ang)*(16+10*rnd(b,k));py+=Math.sin(ang)*(16+10*rnd(b,k));br.push([px,py])}
    line(br,.5,.7)}
}

/* ============ 1. Дым и нить ============ */
function fx1(g,u){
  const I=ST.i,O=ST.o,W=W0,H=H0,cx=W*.5,base=H*.9,hgt=H*.8,cy0=base-hgt*.42,hit=.3;
  const eo=ease(O),bump=Math.max(0,1-Math.abs(I-hit)/.09),flashO=O<.3?Math.sin(PI*O/.3):0;
  const sm=sstep(hit-.02,1,I),smOut=1-sstep(.15,1,O);
  const thr=s=>[cx+Math.sin(TAU*(s*1.5-u))*(20+72*s)+Math.sin(TAU*(s*3.4+u*2))*9*s, base-s*hgt];
  add(g);
  glow(g,'red',cx,cy0,430,.62*P.I*(.88+.12*Math.sin(TAU*u*2))*(.25+.75*sm)*(1-sstep(.2,1,O)),base*.6);
  glow(g,'red',cx,base-6,260,.30*P.I*sm*smOut,90);
  nrm(g);
  for(let i=0;i<9;i++){const p=fract(u+i/9);
    puff(g,i,cx+(p-.5)*880*(1+eo),base+8+Math.sin(i*3)*12,(120+50*rnd(i,1))*(.6+.4*sm)*(1+eo),i*1.3+p*.8,env(p)*.75*sm*smOut,.12*P.I)}
  const N=cnt(44),ps=[];
  for(let i=0;i<N;i++){
    const p=fract(u+i/N),[tx,ty]=thr(p);
    const off=Math.sin(TAU*(rnd(i,1)+p*(1+rnd(i,2))))*(16+120*p);
    let x=tx*.7+cx*.3+off,y=ty+(rnd(i,3)-.5)*36,r=(46+140*Math.pow(p,.85))*(.8+.4*rnd(i,4));
    const lit=Math.exp(-((x-tx)*(x-tx))/(r*r*.5))*.3*P.I*(1-.5*p)*(1+flashO*2.5+bump*1.5);
    x=cx+(x-cx)*(1+1.6*eo);y=cy0+(y-cy0)*(1+.5*eo);r*=(.55+.45*sm)*(1+1.3*eo);
    ps.push({i,p,x,y,r,a:Math.min(1,env(p)*1.25)*sm*smOut,lit,rot:i*1.7+p*(i%2?1.1:-1.1)});
  }
  ps.forEach(q=>{if(q.i%2===0)puff(g,q.i,q.x,q.y,q.r,q.rot,q.a,q.lit)});
  // нить
  add(g);g.lineCap='butt';
  const SEG=72,rv=sstep(0,hit,I)*1.05,tk=Math.min(2.2,(1+1.6*bump+flashO*1.5))*(1-sstep(0,.4,O));
  let prev=thr(0);
  const passes=[[36,.12,'#ff1408'],[19,.28,'#ff2a1a'],[8,.9,'#ff4a30'],[3.4,1,'#ffe0cc']];
  for(let k=1;k<=SEG;k++){
    const s=k/SEG,cur=thr(s);
    let vis=sstep(0,.1,s)*(1-sstep(.86,1,s));
    vis*=.5+.5*(.5+.5*Math.sin(TAU*(s*2.5-u*2)));
    vis*=sstep(1-rv-.03,1-rv,s);
    const w=(.5+Math.pow(Math.sin(PI*s),.5))/1.15;
    passes.forEach(([pw,pa,col])=>{g.strokeStyle=col;g.lineWidth=pw*w;g.globalAlpha=clamp(vis*pa*Math.min(P.I,1.4)*tk*GA);
      g.beginPath();g.moveTo(prev[0],prev[1]);g.lineTo(cur[0],cur[1]);g.stroke()});
    prev=cur;
  }
  const sp=fract(u),[px,py]=thr(.1+.8*sp);
  glow(g,'hot',px,py,70,.7*P.I*Math.sin(PI*sp)*tk/2);
  // молния при появлении
  if(I<.62&&I>0){const top=thr(1),bot=thr(0);
    bolt(g,top[0]+40,-30,bot[0],bot[1],Math.floor(I*26),sstep(0,hit,I),1-sstep(hit+.02,hit+.3,I));}
  glow(g,'hot',thr(0)[0],thr(0)[1],300,1.1*bump*P.I);
  wash(g,.22*bump*P.I,'#ff5a3a');
  // руны
  const M=cnt(16),rs=[];
  for(let j=0;j<M;j++){
    const c=(()=>{const x=u*2+(j*.618%1),f=Math.floor(x);return{p:x-f,c:((f%2)+2)%2}})();
    const s=.1+.78*rnd(j,c.c+5)+.1*c.p,[tx,ty]=thr(s);
    const th=TAU*(u*[1,-1,2][j%3]+rnd(j,1));
    const R=(36+34*rnd(j,2))*(.65+.7*s),dep=Math.sin(th);
    let x=tx+Math.cos(th)*R,y=ty+dep*R*.3-c.p*32;
    const iv=clamp((I-.5)*3-rnd(j,30)*.8),ov=1-clamp(O*2.2-rnd(j,31)*.5);
    x+=(x-cx)*eo*2.2;y+=(y-cy0)*eo*1.2;
    rs.push({id:Math.floor(rnd(j,c.c+9)*NR()),x,y,dep,size:(28+20*rnd(j,3))*(.85+.2*dep),
      a:env(c.p)*flick(u,j)*(.5+.5*(dep*.5+.5))*iv*ov,hot:(flick(u,j)>.98&&c.p<.6)||(iv<1&&iv>0)||O>0&&O<.3,rot:Math.cos(th)*.18+Math.sin(TAU*(u+j*.1))*.2});
  }
  const dr=r=>{glow(g,'red',r.x,r.y,r.size*1.3,.25*r.a*P.I);rune(g,r.id,r.x,r.y,r.size,r.rot,r.a*Math.min(P.I,1.3),r.hot)};
  add(g);rs.filter(r=>r.dep<0).forEach(dr);
  nrm(g);
  ps.forEach(q=>{if(q.i%2===1)puff(g,q.i,q.x,q.y,q.r,q.rot,q.a*.78,q.lit)});
  // дымчатая вспышка при завершении
  if(O>0){for(let k=0;k<14;k++){const ang=TAU*k/14+rnd(k,40),d=eo*(260+120*rnd(k,41));
    puff(g,k,cx+Math.cos(ang)*d,cy0+Math.sin(ang)*d*.7,70+140*eo,k,Math.sin(PI*O)*.85,.25*P.I*(1-eo))}}
  add(g);
  rs.filter(r=>r.dep>=0).forEach(dr);
  for(let i=0;i<cnt(34);i++){
    const p=fract(u*(1+i%2)+rnd(i,5)),[tx,ty]=thr(.05+.9*p);
    const a=env(p)*(.5+.5*flick(u,i))*sstep(.5,1,I)*(1-sstep(0,.6,O));
    glow(g,'hot',tx+Math.sin(TAU*(rnd(i,6)+p))*(30+50*rnd(i,7)),ty-20*p,5+4*rnd(i,8),a*.9);
  }
  glow(g,'hot',cx,cy0,340,1.15*flashO*P.I);
  wash(g,.26*flashO*P.I,'#ff4a2a');
}

/* ============ 2. Пучок рун ============ */
function fx2(g,u){
  const I=ST.i,O=ST.o,W=W0,H=H0,cx=W*.5,gy=H*.78;
  const shK=sstep(0,.45,I)*(1-sstep(.55,1,O)),bh=sstep(.05,.6,I)*(1-sstep(.2,.85,O)),bw=sstep(.05,.8,I)*(1-sstep(.35,1,O));
  const spread=.3+.7*sstep(.1,.9,I),bumpIn=Math.max(0,1-Math.abs(I-.3)/.16),bumpOut=O>.55?Math.sin(PI*(O-.55)/.45):0;
  nrm(g);
  glow(g,'dark',cx,gy,360*(.15+.85*shK),.95*shK,96*(.15+.85*shK));
  glow(g,'dark',cx,gy,190*(.15+.85*shK),.8*shK*(.88+.12*Math.sin(TAU*u*2)),52*(.15+.85*shK));
  add(g);
  glow(g,'red',cx,gy,230*(.2+.8*shK),.55*P.I*shK*(.85+.15*Math.sin(TAU*u*3)),62*(.2+.8*shK));
  glow(g,'hot',cx,gy-4,70,.6*P.I*shK,20);
  glow(g,'hot',cx,gy-4,190,1.0*bumpIn*P.I,60);
  glow(g,'hot',cx,gy-4,150,1.0*bumpOut*P.I,44);
  for(let k=0;k<2;k++){const p=fract(u+k*.5);g.strokeStyle='#ff3a22';g.lineWidth=2;g.globalAlpha=clamp(Math.pow(1-p,2)*.55*P.I*shK*GA);
    g.beginPath();g.ellipse(cx,gy,40+250*p,(40+250*p)*.27,0,0,TAU);g.stroke()}
  // первичная волна при появлении
  if(I<.6&&I>0){const q=I/.6;g.strokeStyle='#ff6a4a';g.lineWidth=4*(1-q)+1;g.globalAlpha=clamp((1-q)*.9*P.I*GA);g.beginPath();g.ellipse(cx,gy,10+330*ease(q),(10+330*ease(q))*.27,0,0,TAU);g.stroke()}
  const rays=[[-.26,.5,430,0],[-.12,.8,520,1],[0,1,600,2],[.13,.75,500,3],[.27,.5,420,4],[-.05,.4,360,5],[.06,.45,380,6]];
  if(bh>.02)rays.forEach(([ang,wd,hh,k])=>{
    const f=.65+.35*Math.sin(TAU*(u*[1,2,1,3,2,1,2][k]+k*.31));
    g.save();g.translate(cx,gy-6);g.rotate(ang*spread);g.globalAlpha=clamp(.62*f*P.I*Math.min(1,bh*3)*GA);
    const w=190*wd*(.3+.7*bw),h=hh*bh;g.drawImage(BEAM,-w/2,-h,w,h);g.restore();
  });
  const N=cnt(26),L=[];
  for(let j=0;j<N;j++){
    const p=fract(u+j/N),e=1-Math.pow(1-p,2.1);
    const phi=(rnd(j,1)-.5)*.95,Hj=190+270*rnd(j,2);
    const iv=clamp((I*1.6-rnd(j,20)*.8)*2.5),ov=1-clamp((O*1.5-rnd(j,21)*.5)*2.5);
    const x=cx+(rnd(j,3)-.5)*70*(1-p)+Math.sin(phi)*e*Hj*.9+Math.sin(TAU*(p*1.5+rnd(j,4)))*9+Math.sin(phi)*O*O*90;
    const y=gy-8-Math.cos(phi)*e*Hj-O*O*(140+160*rnd(j,22));
    L.push({y,f:()=>{const s=(20+24*rnd(j,5))*(.4+.75*Math.pow(Math.sin(PI*Math.min(p*1.15,1)),.6));
      const a=env(p)*flick(u,j)*iv*ov;
      glow(g,'red',x,y,s*1.6,.3*a*P.I);
      rune(g,Math.floor(rnd(j,6)*NR()),x,y,s,phi*.7+Math.sin(TAU*(p+rnd(j,7)))*.25,a*Math.min(P.I,1.3),p<.35||flick(u,j)>.99||(iv>0&&iv<1))}});
  }
  L.sort((a,b)=>b.y-a.y).forEach(o=>o.f());
  for(let i=0;i<cnt(30);i++){const p=fract(u*(1+i%2)+rnd(i,8)),e=1-Math.pow(1-p,1.6);
    glow(g,'hot',cx+(rnd(i,9)-.5)*300*e,gy-e*(120+330*rnd(i,10)),4+4*rnd(i,11),env(p)*.85*sstep(.3,.9,I)*(1-sstep(0,.6,O)))}
}

/* ============ 3. Ритуальный круг ============ */
function fx3(g,u){
  const I=ST.i,O=ST.o,W=W0,H=H0,cx=W*.5,cy=H*.5,R0=330,TILT=1;
  const rk=.03+.97*ease(sstep(0,.85,I)),R=R0*rk;
  const ca=sstep(0,.2,I)*(1-sstep(.3,.75,O));
  const charge=sstep(0,.35,O)*(1-sstep(.35,.7,O)),bq=sstep(.35,1,O);
  const bumpIn=I<.4?Math.sin(PI*I/.4):0,GA0=GA;
  nrm(g);GA=GA0*ca;
  glow(g,'dark',cx,cy,R*1.22,.95,R*1.22*TILT);
  add(g);
  glow(g,'red',cx,cy,R*1.05,.42*P.I*(.88+.12*Math.sin(TAU*u*2)),R*1.05*TILT);
  glow(g,'hot',cx,cy,80,.55*P.I,80*TILT);
  GA=GA0;
  glow(g,'hot',cx,cy,190,1.0*bumpIn*P.I,190*TILT);
  GA=GA0*ca;
  g.save();g.translate(cx,cy);g.scale(1,TILT);
  const ring=(r,w,col,a,dash,off)=>{g.strokeStyle=col;g.lineWidth=w;g.globalAlpha=clamp(a*GA);g.setLineDash(dash||[]);g.lineDashOffset=off||0;g.beginPath();g.arc(0,0,r,0,TAU);g.stroke();g.setLineDash([])};
  [[R,16,'#ff1408',.10],[R,7,'#ff2a1a',.25],[R,2.4,'#ff6a4a',.9]].forEach(([r,w,c,a])=>ring(r,w,c,a*P.I));
  [[R*.66,9,'#ff1408',.1],[R*.66,2,'#ff4a30',.75]].forEach(([r,w,c,a])=>ring(r,w,c,a*P.I));
  ring(R*1.07,2.2,'#ff5a3a',.7*P.I,[10,14],u*24*6);
  ring(R*.6,1.6,'#ff5a3a',.6*P.I,[4,8],-u*12*10);
  // вспышка по окружности перед взрывом
  if(charge>.01){ring(R,10+26*charge,'#ff3a22',charge*.55*P.I);ring(R,5+8*charge,'#ff9a70',charge*.9);ring(R,2.5,'#fff0e6',charge)}
  const rot=u*TAU/7,SR=R*.63;
  [[9,.12,'#ff1408'],[2,.85,'#ff5a3a']].forEach(([w,a,c])=>{
    g.strokeStyle=c;g.lineWidth=w;g.globalAlpha=clamp(a*P.I*GA);g.beginPath();
    for(let k=0;k<7;k++){const a1=rot+TAU*k/7,a2=rot+TAU*((k+3)%7)/7;
      g.moveTo(Math.cos(a1)*SR,Math.sin(a1)*SR);g.lineTo(Math.cos(a2)*SR,Math.sin(a2)*SR)}
    g.stroke()});
  const N=cnt(16);
  for(let j=0;j<N;j++){
    const th=TAU*(j/N+u),b=Math.pow(fract(-u*2+j/N),3),iv=clamp((I*1.3-(j/N)*.5-.15)*4);
    const a=(.4+.6*b)*(.85+.15*flick(u,j))*iv;
    g.save();g.rotate(th);g.translate(R*.83,0);g.rotate(PI/2);
    glow(g,'red',0,0,42,.35*a*P.I);
    rune(g,Math.floor(rnd(j,1)*NR()),0,0,44,0,a*Math.min(P.I,1.3),b>.7||charge>.4||(iv>0&&iv<1));
    g.restore();
  }
  g.restore();
  for(let k=0;k<2;k++){const p=fract(u+k*.5);g.save();g.translate(cx,cy);g.scale(1,TILT);
    g.strokeStyle='#ff3a22';g.lineWidth=3;g.globalAlpha=clamp(Math.pow(1-p,2)*.6*P.I*GA);g.beginPath();g.arc(0,0,R*.15+R*.9*p,0,TAU);g.stroke();g.restore()}
  GA=GA0;
  // ударная волна по окружности
  if(bq>0){add(g);g.save();g.translate(cx,cy);g.scale(1,TILT);
    const rr=R0*(1+.8*ease(bq));
    [[26,.25,'#ff2a1a'],[10,.7,'#ff8a60'],[3.5,1,'#fff0e6']].forEach(([w,a,c])=>{g.strokeStyle=c;g.lineWidth=w*(1-bq*.6);g.globalAlpha=clamp(a*Math.pow(1-bq,1.3)*P.I*GA);g.beginPath();g.arc(0,0,rr,0,TAU);g.stroke()});
    g.restore();glow(g,'hot',cx,cy,R0*(1.1+.8*bq),.5*(1-bq)*P.I,R0*(1.1+.8*bq)*TILT)}
  return;
  const rin=sstep(.55,1,I),rout=1-sstep(0,.5,O);
  nrm(g);
  for(let i=0;i<12;i++){const th=TAU*(i/12)+u*TAU;
    puff(g,i,cx+Math.cos(th)*R*1.02,cy+Math.sin(th)*R*1.02*TILT,(80+30*rnd(i,1))*rk,i,.34*rin*rout,.1*P.I)}
  add(g);
  // руны, сорванные ударной волной
  if(bq>0){for(let j=0;j<N;j++){const th=TAU*(j/N+u),gx=cx+Math.cos(th)*R0*.83*(1+.5*bq),gyy=cy+Math.sin(th)*R0*.83*TILT*(1+.5*bq)-ease(bq)*(120+240*rnd(j,50));
    const a=(1-bq)*Math.min(1,bq*8);glow(g,'red',gyy===0?0:gx,gyy,50,.4*a*P.I);
    rune(g,Math.floor(rnd(j,1)*NR()),gx,gyy,44*(1+.4*bq),Math.sin(TAU*(bq+rnd(j,51)))*.4,a,true)}}
  const RN=cnt(20);
  for(let i=0;i<RN;i++){
    const p=fract(u+i/RN),a0=TAU*rnd(i,1),rr=R0*(.55+.4*rnd(i,2))*(1-.35*p);
    const x=cx+Math.cos(a0+p*.9)*rr,y=cy+Math.sin(a0+p*.9)*rr*TILT-p*(150+230*rnd(i,3));
    const s=(20+18*rnd(i,4))*(.6+.6*Math.sin(PI*p)),a=env(p)*flick(u,i)*rin*rout;
    glow(g,'red',x,y,s*1.6,.3*a*P.I);
    rune(g,Math.floor(rnd(i,5)*NR()),x,y,s,Math.sin(TAU*(p+rnd(i,6)))*.3,a*Math.min(P.I,1.3),p<.3);
  }
  for(let i=0;i<cnt(36);i++){const p=fract(u*(1+i%2)+rnd(i,8)),a0=TAU*rnd(i,9),rr=R0*(.2+.8*rnd(i,10));
    glow(g,'hot',cx+Math.cos(a0)*rr,cy+Math.sin(a0)*rr*TILT-p*(80+200*rnd(i,11)),4+4*rnd(i,12),env(p)*.85*rin*rout)}
  wash(g,.12*charge*P.I,'#ff3a22');
}


function fx3Air(g,u){const I=ST.i,O=ST.o,W=W0,H=H0,cx=W*.5,cy=H*.63,R0=330,TILT=.64,R=R0,rk=1,N=cnt(16),bq=0,charge=0;
  const rin=sstep(.55,1,I),rout=1-sstep(0,.5,O);
  nrm(g);
  for(let i=0;i<12;i++){const th=TAU*(i/12)+u*TAU;
    puff(g,i,cx+Math.cos(th)*R*1.02,cy+Math.sin(th)*R*1.02*TILT,(80+30*rnd(i,1))*rk,i,.34*rin*rout,.1*P.I)}
  add(g);
  // руны, сорванные ударной волной
  if(bq>0){for(let j=0;j<N;j++){const th=TAU*(j/N+u),gx=cx+Math.cos(th)*R0*.83*(1+.5*bq),gyy=cy+Math.sin(th)*R0*.83*TILT*(1+.5*bq)-ease(bq)*(120+240*rnd(j,50));
    const a=(1-bq)*Math.min(1,bq*8);glow(g,'red',gyy===0?0:gx,gyy,50,.4*a*P.I);
    rune(g,Math.floor(rnd(j,1)*NR()),gx,gyy,44*(1+.4*bq),Math.sin(TAU*(bq+rnd(j,51)))*.4,a,true)}}
  const RN=cnt(20);
  for(let i=0;i<RN;i++){
    const p=fract(u+i/RN),a0=TAU*rnd(i,1),rr=R0*(.55+.4*rnd(i,2))*(1-.35*p);
    const x=cx+Math.cos(a0+p*.9)*rr,y=cy+Math.sin(a0+p*.9)*rr*TILT-p*(150+230*rnd(i,3));
    const s=(20+18*rnd(i,4))*(.6+.6*Math.sin(PI*p)),a=env(p)*flick(u,i)*rin*rout;
    glow(g,'red',x,y,s*1.6,.3*a*P.I);
    rune(g,Math.floor(rnd(i,5)*NR()),x,y,s,Math.sin(TAU*(p+rnd(i,6)))*.3,a*Math.min(P.I,1.3),p<.3);
  }
  for(let i=0;i<cnt(36);i++){const p=fract(u*(1+i%2)+rnd(i,8)),a0=TAU*rnd(i,9),rr=R0*(.2+.8*rnd(i,10));
    glow(g,'hot',cx+Math.cos(a0)*rr,cy+Math.sin(a0)*rr*TILT-p*(80+200*rnd(i,11)),4+4*rnd(i,12),env(p)*.85*rin*rout)}
  wash(g,.12*charge*P.I,'#ff3a22');
}

/* ============ 4. Печать-сфера ============ */
function fx4(g,u){
  const I=ST.i,O=ST.o,W=W0,H=H0,cx=W*.5,cy=H*.5;
  let kS=1,ga=1,spin=0,q=0,collapse=0;
  if(I<1){kS=easeBack(sstep(0,.8,I));ga=sstep(0,.2,I);spin=-.6*(1-sstep(0,.8,I))}
  if(O>0){
    if(O<.55){collapse=O/.55;kS=1-.84*ease(collapse);spin=.6*collapse}
    else{q=(O-.55)/.45;kS=.16+2.3*ease(q);ga=1-sstep(.05,.95,q);spin=.6}
  }
  const bumpIn=I<.45?Math.sin(PI*I/.45):0,R=215*(1+.025*Math.sin(TAU*u*2))*kS,szk=clamp(kS,.4,1.35);
  const GA0=GA;GA=GA0*ga;
  const rings=[{t:.5,r:.2,n:9,d:1},{t:-.95,r:1.0,n:11,d:-1},{t:1.25,r:-.6,n:8,d:1},{t:.08,r:2.3,n:12,d:-1}];
  const items=[],lines=[];
  const proj=(x,y,z)=>{const sc=1/(1-z/1500);return{x:cx+x*sc,y:cy+y*sc,sc,z}};
  rings.forEach((rg,k)=>{
    const P3=(phi)=>{let x=R*Math.cos(phi),y=0,z=R*Math.sin(phi);
      const y2=y*Math.cos(rg.t)-z*Math.sin(rg.t),z2=y*Math.sin(rg.t)+z*Math.cos(rg.t);
      const x3=x*Math.cos(rg.r)-y2*Math.sin(rg.r),y3=x*Math.sin(rg.r)+y2*Math.cos(rg.r);return proj(x3,y3,z2)};
    let pr=P3(spin*rg.d);
    for(let s=1;s<=72;s++){const c=P3(TAU*s/72+spin*rg.d);lines.push({a:pr,b:c,z:(pr.z+c.z)/2});pr=c}
    const n=cnt(rg.n);
    for(let j=0;j<n;j++){
      const qq=P3(TAU*(rg.d*u+j/n)+spin*rg.d);
      items.push({q:qq,id:Math.floor(rnd(j,k+20)*NR()),j:j+k*20,life:.55+.45*Math.sin(TAU*(u*2+rnd(j,k)+k*.2))});
    }
  });
  add(g);
  glow(g,'red',cx,cy,Math.max(30,R*1.9),.32*P.I*(.85+.15*Math.sin(TAU*u*3)));
  g.lineWidth=1.3;g.strokeStyle='#ff3a22';
  const dl=(back)=>lines.filter(l=>back?l.z<0:l.z>=0).forEach(l=>{
    g.globalAlpha=clamp((back?.09:.22)*P.I*GA);g.beginPath();g.moveTo(l.a.x,l.a.y);g.lineTo(l.b.x,l.b.y);g.stroke()});
  dl(true);
  const dr=(it)=>{const {q:pp}=it,dep=pp.z/Math.max(R,1),s=(46+10*dep)*pp.sc*(.9+.2*it.life)*szk;
    const a=(.55+.45*(dep*.5+.5))*it.life*flick(u,it.j);
    glow(g,'red',pp.x,pp.y,s*1.5,.28*a*P.I);
    rune(g,it.id,pp.x,pp.y,s,Math.sin(TAU*(u+it.j*.13))*.16,a*Math.min(P.I,1.3),(flick(u,it.j)>.98&&dep>0)||collapse>.4)};
  items.filter(i=>i.q.z<0).sort((a,b)=>a.q.z-b.q.z).forEach(dr);
  nrm(g);
  const cr=112*kS;
  if(cr>2){
    g.globalAlpha=clamp(GA);
    const og=g.createRadialGradient(cx-30*kS,cy-36*kS,cr*.09,cx,cy,cr);
    og.addColorStop(0,'#1c0809');og.addColorStop(.7,'#0b0304');og.addColorStop(.93,'rgba(120,14,10,.95)');og.addColorStop(1,'rgba(255,60,40,0)');
    g.fillStyle=og;g.beginPath();g.arc(cx,cy,cr,0,TAU);g.fill();
    g.save();g.beginPath();g.arc(cx,cy,cr*.93,0,TAU);g.clip();add(g);
    g.strokeStyle='#ff4a30';g.lineCap='round';
    for(let k=0;k<6;k++){
      const a0=TAU*(k/6+rnd(k,1)*.1)+Math.sin(TAU*(u+k*.2))*.05;
      g.globalAlpha=clamp((.35+.5*Math.sin(TAU*(u*2+k*.37))+collapse*.5)*P.I*GA);g.lineWidth=1.6;
      g.beginPath();let r=8*kS,a=a0;g.moveTo(cx+Math.cos(a)*r,cy+Math.sin(a)*r);
      for(let s=0;s<7;s++){r+=(13+6*rnd(k,s+3))*kS;a+=(rnd(k,s+9)-.5)*.6;g.lineTo(cx+Math.cos(a)*r,cy+Math.sin(a)*r)}
      g.stroke()}
    glow(g,'hot',cx,cy,44*kS+collapse*30,(.6+collapse*.6)*P.I*(.8+.2*Math.sin(TAU*u*3)));
    glow(g,'red',cx,cy,cr*.98,.35*P.I);
    g.restore();
  }
  add(g);
  glow(g,'red',cx,cy,Math.max(20,190*kS),.30*P.I);
  dl(false);
  items.filter(i=>i.q.z>=0).sort((a,b)=>a.q.z-b.q.z).forEach(dr);
  for(let i=0;i<cnt(30);i++){const th=TAU*(u*(1+i%2)+rnd(i,1)),ph=(rnd(i,2)-.5)*PI,r=R*(1.05+.4*rnd(i,3));
    glow(g,'hot',cx+Math.cos(th)*Math.cos(ph)*r,cy+Math.sin(ph)*r*.9,4+3*rnd(i,4),.7*(.5+.5*Math.sin(TAU*(u*3+rnd(i,5)))))}
  GA=GA0;
  // вспышки: рождение и взрыв
  glow(g,'hot',cx,cy,260,1.1*bumpIn*P.I);
  if(I<.7&&I>0){const s=I/.7;g.strokeStyle='#ff6a4a';g.lineWidth=5*(1-s)+1;g.globalAlpha=clamp((1-s)*.9*P.I*GA);g.beginPath();g.arc(cx,cy,20+330*ease(s),0,TAU);g.stroke()}
  if(O>=.55){
    glow(g,'hot',cx,cy,320,1.3*(1-q)*P.I);
    [[22,.25,'#ff2a1a'],[8,.75,'#ff8a60'],[3,1,'#fff0e6']].forEach(([w,a,c])=>{g.strokeStyle=c;g.lineWidth=w*(1-q*.6);g.globalAlpha=clamp(a*Math.pow(1-q,1.3)*P.I*GA);g.beginPath();g.arc(cx,cy,40+560*ease(q),0,TAU);g.stroke()});
    wash(g,.3*(1-q)*(1-q)*P.I,'#ff3a22');
  }
  if(collapse>0)glow(g,'hot',cx,cy,120+80*collapse,.6*collapse*P.I);
}

/* ============ 5. Вихрь ============ */
function fx5(g,u){
  const I=ST.i,O=ST.o,W=W0,H=H0,cx=W*.5,base=H*.86,hgt=H*.74;
  const hf=sstep(0,.95,I)*1.16,grow=.35+.65*sstep(0,.9,I),gk=sstep(0,.4,I)*(1-sstep(.3,1,O)),bumpIn=I<.35?Math.sin(PI*I/.35):0;
  const disp=(s)=>({dx:(80+360*rnd(s,60))*Math.pow(O,1.6)*(rnd(s,62)<.15?-.5:1),dy:-(40+220*rnd(s,61))*O});
  const place=(p,ph,s)=>{
    const th=TAU*(1.8*p+ph),r=(46+175*Math.pow(p,.9))*grow,d=disp(s);
    const vis=(I<1?1-sstep(hf-.15,hf,p):1)*(1-clamp(O*1.7-rnd(s,63)*.6));
    return{x:cx+Math.cos(th)*r+d.dx,y:base-p*hgt*(.6+.4*grow)+Math.sin(th)*r*.26+d.dy,dep:Math.sin(th),vis};
  };
  nrm(g);
  glow(g,'dark',cx,base+6,300*gk,.9*gk,80*gk);
  add(g);
  glow(g,'red',cx,base,250*(.2+.8*gk),.5*P.I*gk*(.85+.15*Math.sin(TAU*u*2)),68*(.2+.8*gk));
  glow(g,'red',cx,base-hgt*.4,330,.16*P.I*gk);
  glow(g,'hot',cx,base,220,1.0*bumpIn*P.I,60);
  for(let k=0;k<2;k++){const p=fract(u+k*.5);g.strokeStyle='#ff3a22';g.lineWidth=2;g.globalAlpha=clamp(Math.pow(1-p,2)*.5*P.I*gk*GA);
    g.beginPath();g.ellipse(cx,base,40+230*p,(40+230*p)*.26,0,0,TAU);g.stroke()}
  if(I<.5&&I>0){const q=I/.5;g.strokeStyle='#ff6a4a';g.lineWidth=4*(1-q)+1;g.globalAlpha=clamp((1-q)*.9*P.I*GA);g.beginPath();g.ellipse(cx,base,10+300*ease(q),(10+300*ease(q))*.26,0,0,TAU);g.stroke()}
  nrm(g);
  const NP=cnt(26);
  for(let i=0;i<NP;i++){const p=fract(u+i/NP),q=place(p,rnd(i,1),100+i),rr=(40+90*p)*(.8+.4*rnd(i,2))*(1+O*1.2);
    puff(g,i,q.x*.85+cx*.15,q.y,rr,i*1.9+p+O*2,env(p)*.72*q.vis*(1-sstep(.1,.9,O)),.22*P.I*(1-.4*p))}
  add(g);
  const N=cnt(30),L=[];
  for(let j=0;j<N;j++){
    const p0=fract(u+j/N),ph=rnd(j,1),id=Math.floor(rnd(j,2)*NR());
    for(let t=4;t>=0;t--){
      const p=p0-t*.012;if(p<0)continue;
      const q=place(p,ph,j),fade=t===0?1:(1-t/5)*.45;
      const s=(30+18*rnd(j,3))*(1-.28*p)*(.78+.28*q.dep)*(t===0?1:1-t*.08)*(1-.3*O);
      L.push({z:q.dep,f:()=>{
        const a=env(p0)*flick(u,j)*fade*(.55+.45*(q.dep*.5+.5))*q.vis;
        if(t===0)glow(g,'red',q.x,q.y,s*1.5,.3*a*P.I);
        rune(g,id,q.x,q.y,s,q.dep*.25+Math.sin(TAU*(p0*2+ph))*.2+O*rnd(j,64)*4,a*Math.min(P.I,1.3),(t===0&&p0<.3)||(I<1&&t===0))}});
    }
  }
  L.sort((a,b)=>a.z-b.z).forEach(o=>o.f());
  for(let i=0;i<cnt(60);i++){const p=fract(u*(1+i%2)+rnd(i,4)),q=place(p,rnd(i,5),200+i),jit=(rnd(i,6)-.5)*50;
    glow(g,'hot',q.x+jit,q.y-10*p,3+3*rnd(i,7),env(p)*.9*q.vis)}
}

