function render(g,fx,u,w,h){
  g.setTransform(1,0,0,1,0,0);g.globalAlpha=1;nrm(g);
  g.save();g.scale(w/W0,h/H0);
  backdrop(g,W0,H0);
  GA=sstep(0,.015,ST.i)*(1-sstep(.965,1,ST.o));
  fx.f(g,u);
  GA=1;
  g.restore();g.globalAlpha=1;nrm(g);
}


